fn has_common_element(a: &[i32], b: &[i32]) -> bool {
    // If either slice is empty, return false
    if a.is_empty() || b.is_empty() {
        return false;
    }

    // Use a HashSet to track elements in the first slice
    use std::collections::HashSet;
    let set: HashSet<_> = a.iter().collect();

    // Check if any element in the second slice exists in the HashSet
    for &item in b {
        if set.contains(&item) {
            return true; // Found a common element
        }
    }

    false // No common elements found
}

fn slice_contains(s: &[i32], val: i32) -> bool {
    // Iterate through the slice and check for the value
    for &item in s {
        if item == val {
            return true; // Value found in the slice
        }
    }

    false // Value not found in the slice
}